/**
 * Delivery pump: dequeue → skip duplicates → deliver → ack + record, or requeue
 * with backoff on failure. The sink and the dedup guard record a delivery only
 * after the downstream has accepted the message, so a retry (for example an
 * attempt that failed after the downstream had already accepted) can never
 * re-deliver an id that was already delivered. Requeued messages are re-inserted
 * ahead of any queued message with the same key, so per-key ordering is
 * preserved across retries while messages of other keys are not blocked.
 */
import { retryWithBackoff } from './retry.js'

export function createPump({ queue, dedup, sink, clock, processMessage, maxAttempts = 3 }) {
  return {
    run(steps = Infinity) {
      for (let i = 0; i < steps; i++) {
        const message = queue.dequeue()
        if (message === null) break
        if (message.retryAt !== undefined && clock.now() < message.retryAt) {
          queue.requeue(message)
          continue
        }
        if (dedup.isDuplicate(message.id, clock.now())) {
          queue.ack(message.id)
          continue
        }
        const ok = processMessage(message)
        if (!ok) {
          message.attempts += 1
          if (message.attempts >= maxAttempts) {
            queue.ack(message.id)
            sink.failed(message)
            continue
          }
          message.retryAt = clock.now() + retryWithBackoff(clock).delayFor(message.attempts)
          queue.requeue(message)
          continue
        }
        sink.emit(message)
        queue.ack(message.id)
        dedup.record(message.id, clock.now())
      }
    },
  }
}

/**
 * FIFO message queue. Messages are { id, key, payload }. dequeue removes and
 * returns the oldest message whose id has not been finalized; ack finalizes a
 * message; failed messages are put back on the queue for a later retry.
 *
 * requeue re-inserts a message ahead of the first queued message that shares its
 * key (or appends it when none does). A retried message was enqueued earlier
 * than every queued message with the same key, so this keeps same-key messages
 * in enqueue order across retries while letting messages of other keys pass.
 */
export function createQueue() {
  const entries = []
  const done = new Set()
  return {
    enqueue(message) {
      entries.push({ ...message, attempts: message.attempts ?? 0 })
    },
    dequeue() {
      for (let i = 0; i < entries.length; i++) {
        if (!done.has(entries[i].id)) return entries.splice(i, 1)[0]
      }
      return null
    },
    ack(id) {
      done.add(id)
    },
    requeue(message) {
      const index = entries.findIndex((entry) => entry.key === message.key)
      if (index === -1) entries.push(message)
      else entries.splice(index, 0, message)
    },
    pending() {
      return entries.filter((entry) => !done.has(entry.id))
    },
  }
}

