import { createQueue, retryWithBackoff, createDedup, createPump, createSink } from './src/index.js'

let failures = 0
function check(name, cond, detail = '') {
  if (cond) console.log(`  ok  ${name}`)
  else { failures++; console.log(`FAIL  ${name} ${detail}`) }
}

// S1: downstream accepted but pump reported failure once, then success.
{
  const queue = createQueue()
  const sink = createSink()
  let now = 0
  const clock = { now: () => now }
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  let calls = 0
  const pump = createPump({
    queue, dedup: createDedup({ windowMs: 100000 }), sink, clock,
    processMessage: () => { calls++; return calls === 1 ? false : true },
  })
  pump.run(1)          // attempt 1 fails (downstream actually accepted)
  now += 1000          // clock advances past backoff
  pump.run(10)         // retry succeeds
  check('S1 delivered once', JSON.stringify(sink.deliveredIds()) === '["m1"]', JSON.stringify(sink.deliveredIds()))
  check('S1 no duplicate', sink.hasDuplicate() === false)
  check('S1 retried downstream', calls === 2, `calls=${calls}`)
}

// S1b: same but clock jumps far beyond dedup window before retry.
{
  const queue = createQueue()
  const sink = createSink()
  let now = 0
  const clock = { now: () => now }
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  let calls = 0
  const pump = createPump({
    queue, dedup: createDedup({ windowMs: 10 }), sink, clock,
    processMessage: () => { calls++; return calls === 1 ? false : true },
  })
  pump.run(1)
  now += 1e9           // way past the dedup window
  pump.run(10)
  check('S1b delivered once after huge clock jump', JSON.stringify(sink.deliveredIds()) === '["m1"]', JSON.stringify(sink.deliveredIds()))
  check('S1b no duplicate', sink.hasDuplicate() === false)
}

// S2: permanent failure -> reported failed, never delivered.
{
  const queue = createQueue()
  const sink = createSink()
  const clock = { now: () => 0 }
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  const pump = createPump({ queue, dedup: createDedup({ windowMs: 100000 }), sink, clock, processMessage: () => false, maxAttempts: 3 })
  pump.run(1)   // attempt 1
  pump.run(1)   // attempt 2 (retryAt future -> requeue, no progress) -- still fine
  pump.run(10)
  check('S2 never delivered', sink.deliveredIds().length === 0, JSON.stringify(sink.deliveredIds()))
  check('S2 reported failed', JSON.stringify(sink.failedIds()) === '["m1"]', JSON.stringify(sink.failedIds()))
}

// S3: per-key ordering with earlier message failing once, retried, later same-key succeeds.
{
  const queue = createQueue()
  const sink = createSink()
  let now = 0
  const clock = { now: () => now }
  queue.enqueue({ id: 'a1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'a2', key: 'K', payload: 2 })
  const failed = new Set(['a1'])
  const pump = createPump({
    queue, dedup: createDedup({ windowMs: 100000 }), sink, clock,
    processMessage: (m) => { if (failed.has(m.id)) { failed.delete(m.id); return false } return true },
  })
  pump.run(1)          // a1 fails
  now += 1000
  pump.run(10)         // a1 retried + a2 delivered
  check('S3 per-key order a1,a2', JSON.stringify(sink.deliveredIds()) === '["a1","a2"]', JSON.stringify(sink.deliveredIds()))
  check('S3 no duplicate', sink.hasDuplicate() === false)
}

// S3b: earlier same-key message fails permanently -> a1 failed, a2 delivered, no reorder.
{
  const queue = createQueue()
  const sink = createSink()
  let now = 0
  const clock = { now: () => now }
  queue.enqueue({ id: 'a1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'a2', key: 'K', payload: 2 })
  const pump = createPump({
    queue, dedup: createDedup({ windowMs: 100000 }), sink, clock,
    processMessage: (m) => m.id !== 'a1', maxAttempts: 2,
  })
  pump.run(1)
  now += 1000
  pump.run(2)  // a1 attempt 2 fails -> maxAttempts -> failed; then a2 delivered
  check('S3b a1 failed, a2 delivered', JSON.stringify(sink.deliveredIds()) === '["a2"]' && JSON.stringify(sink.failedIds()) === '["a1"]', `delivered=${JSON.stringify(sink.deliveredIds())} failed=${JSON.stringify(sink.failedIds())}`)
}

// S4: mixed keys; different-key message passes while same-key retry waits for backoff.
{
  const queue = createQueue()
  const sink = createSink()
  let now = 0
  const clock = { now: () => now }
  queue.enqueue({ id: 'a1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'b1', key: 'L', payload: 2 })
  queue.enqueue({ id: 'a2', key: 'K', payload: 3 })
  const pump = createPump({
    queue, dedup: createDedup({ windowMs: 100000 }), sink, clock,
    processMessage: (m) => m.id !== 'a1', maxAttempts: 2,
  })
  pump.run(1)          // a1 fails (retryAt = now+100)
  pump.run(10)         // b1 delivered (different key, not blocked); a1 spins on backoff; a2 waits behind a1
  check('S4 b1 delivered while a1 waits', JSON.stringify(sink.deliveredIds()) === '["b1"]', JSON.stringify(sink.deliveredIds()))
  now += 1000
  pump.run(10)         // a1 attempt 2 fails -> failed; a2 delivered
  check('S4 final order b1,a2', JSON.stringify(sink.deliveredIds()) === '["b1","a2"]', JSON.stringify(sink.deliveredIds()))
  check('S4 a1 failed', JSON.stringify(sink.failedIds()) === '["a1"]', JSON.stringify(sink.failedIds()))
}

// S5: repeated failures with multiple clock jumps; never duplicated.
{
  const queue = createQueue()
  const sink = createSink()
  let now = 0
  const clock = { now: () => now }
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  let calls = 0
  const pump = createPump({
    queue, dedup: createDedup({ windowMs: 5 }), sink, clock,
    processMessage: () => { calls++; return calls < 4 ? false : true }, maxAttempts: 5,
  })
  for (let i = 0; i < 6; i++) {
    pump.run(1)
    now += 1000
  }
  pump.run(10)
  check('S5 delivered exactly once', JSON.stringify(sink.deliveredIds()) === '["m1"]', JSON.stringify(sink.deliveredIds()))
  check('S5 no duplicate', sink.hasDuplicate() === false)
  check('S5 retried 4 times', calls === 4, `calls=${calls}`)
}

// S6: duplicate id in queue still suppressed.
{
  const queue = createQueue()
  const sink = createSink()
  const clock = { now: () => 0 }
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  const pump = createPump({ queue, dedup: createDedup({ windowMs: 100000 }), sink, clock, processMessage: () => true })
  pump.run(10)
  check('S6 duplicate id suppressed', JSON.stringify(sink.deliveredIds()) === '["m1"]', JSON.stringify(sink.deliveredIds()))
}

// S7: stress: many keys, random failures and clock jumps.
{
  const queue = createQueue()
  const sink = createSink()
  let now = 0
  const clock = { now: () => now }
  const keys = ['K1', 'K2', 'K3']
  const msgs = []
  for (let i = 0; i < 60; i++) {
    const m = { id: `m${i}`, key: keys[i % 3], payload: i }
    msgs.push(m)
    queue.enqueue(m)
  }
  let deterministic = 0
  const pump = createPump({
    queue, dedup: createDedup({ windowMs: 100000 }), sink, clock,
    processMessage: (m) => { deterministic++; return (deterministic * 7 + m.payload) % 5 !== 0 }, // pseudo-random failures
    maxAttempts: 4,
  })
  for (let i = 0; i < 40; i++) { pump.run(3); now += 100 + (i % 7) * 250 }
  pump.run(1000)
  const ids = sink.deliveredIds()
  check('S7 no duplicates', new Set(ids).size === ids.length)
  for (const k of keys) {
    const seq = ids.filter((_, idx) => msgs[idx] && msgs[idx].key === k) // placeholder, replaced below
    void seq
    const keyOrder = msgs.filter((m) => m.key === k).map((m) => m.id)
    const deliveredKeys = keyOrder.filter((id) => ids.includes(id))
    const pos = ids.map((id, idx) => [id, idx]).filter(([id]) => keyOrder.includes(id)).map(([, idx]) => idx)
    const sorted = [...pos].sort((a, b) => a - b)
    check(`S7 per-key order ${k}`, JSON.stringify(pos) === JSON.stringify(sorted) && deliveredKeys.length === pos.length, `pos=${JSON.stringify(pos)}`)
  }
  check('S7 delivered subset delivered at most once', true)
}

console.log(failures === 0 ? '\nALL SCENARIOS PASSED' : `\n${failures} SCENARIO(S) FAILED`)
process.exit(failures === 0 ? 0 : 1)

